package main

import "fmt"

type Counter struct {
	Name  string
	Count int
}

// IncByValue 拿到的是 Counter 的副本，改副本不会影响调用方。
func IncByValue(c Counter) {
	c.Count++
}

// IncByPointer 拿到的是地址，*c 直接改的就是调用方的那个对象。
func IncByPointer(c *Counter) {
	c.Count++
}

func main() {
	c := Counter{Name: "订单", Count: 1}
	IncByValue(c)
	fmt.Println("值传递后:", c.Count)
	IncByPointer(&c)
	fmt.Println("指针传递后:", c.Count)
}

