package main

import "fmt"

func main() {
	base := []int{1, 2, 3, 4}
	// base[:2] 只指向原底层数组的前两个位置，修改 view 会一起改到 base。
	view := base[:2]
	view[0] = 99
	fmt.Println("base:", base)
	fmt.Println("view:", view)

	// cap 还有空间，append 会直接写进 base 的第三个位置，并不换数组。
	view = append(view, 7)
	fmt.Println("append 后 base:", base)
	fmt.Println("cap:", cap(view))
}

