package main

import "fmt"

// edges[i] 是对象 i 引用的对象；0 是根，2 与 3 互相引用却无人可达。
func main() {
	edges := [][]int{{1}, {}, {3}, {2}}
	marked := make([]bool, len(edges))

	queue := []int{0} // 根对象入队，相当于三色标记里的灰色集合
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		marked[cur] = true // 置黑；真实 GC 对已黑对象会直接跳过
		for _, next := range edges[cur] {
			if !marked[next] {
				queue = append(queue, next) // 引用到的对象置灰入队
			}
		}
	}

	alive := 0
	for _, ok := range marked {
		if ok {
			alive++
		}
	}
	fmt.Println("存活对象:", alive)
	fmt.Println("待回收对象:", len(edges)-alive)
}

