package main

import "fmt"

func main() {
	// 对象 0 是根，可达 1；对象 2 与 3 互相引用，但从根走不到。
	edges := [][]int{{1}, {}, {3}, {2}}

	// TODO: 只统计"被引用次数"看不出循环引用，改成从根出发做可达性标记。
	refs := []int{0, 1, 1, 1}
	alive, garbage := 0, 0
	for _, n := range refs {
		if n == 0 {
			garbage++
		} else {
			alive++
		}
	}
	_ = edges
	fmt.Println("存活对象:", alive)
	fmt.Println("待回收对象:", garbage)
}

