package main

import "fmt"

// 把分片求和抽成函数，两个 goroutine 各算一半，再用 channel 交回结果。
func sumOf(nums []int) int {
	sum := 0
	for _, v := range nums {
		sum += v
	}
	return sum
}

func main() {
	data := []int{1, 2, 3, 4, 5, 6, 7, 8}
	mid := len(data) / 2
	partials := make(chan int, 2)

	go func() { partials <- sumOf(data[:mid]) }()
	go func() { partials <- sumOf(data[mid:]) }()

	total := 0
	for i := 0; i < 2; i++ {
		total += <-partials
	}
	fmt.Println("总分片:", data[:mid], data[mid:])
	fmt.Println("总和:", total)
}

