package main

import (
	"fmt"
	"strconv"
	"strings"
)

// describe 演示反射最常用的思路：面对 interface{} 先看动态类型，再按类型取值处理。
// 真实的 reflect 也是先 TypeOf/ValueOf 得到类型与值，再按 Kind 分支。
func describe(v interface{}) string {
	switch x := v.(type) {
	case int:
		return "整数 " + strconv.Itoa(x*2)
	case string:
		return "字符串 " + strings.ToUpper(x)
	case bool:
		return "布尔 " + strconv.FormatBool(x)
	default:
		return fmt.Sprintf("未知类型 %v", x)
	}
}

func main() {
	fmt.Println(describe(21))
	fmt.Println(describe("go"))
	fmt.Println(describe(true))
	fmt.Println(describe(3.14))
}

